const WithPreview = () => (
  <Main style={{ padding: 24 }}>
    <ThemeToggle />
    <Box title="Карточка" style={{ marginTop: 16 }}>
      Контент меняет оформление при смене темы в toolbar или переключателе.
    </Box>
  </Main>
);

function WithLabel(args: ToggleProps) {
    const [, updateArgs] = useArgs<ToggleProps>();
    const { variant = "switch" } = args;

    return (
        <Toggle
            active
            label="Мои"
            onChange={
              variant === "text"
                ? args.onChange
                : (next) => updateArgs({ active: next })
            } />
    );
}

function SwitchOnly(args: ToggleProps) {
    const [, updateArgs] = useArgs<ToggleProps>();
    const { variant = "switch" } = args;

    return (
        <Toggle
            active={false}
            onChange={
              variant === "text"
                ? args.onChange
                : (next) => updateArgs({ active: next })
            } />
    );
}

function TextOnly(args: ToggleProps) {
    const [, updateArgs] = useArgs<ToggleProps>();
    const { variant = "switch" } = args;

    return (
        <Toggle
            variant="text"
            label="Подпись без переключателя"
            onChange={
              variant === "text"
                ? args.onChange
                : (next) => updateArgs({ active: next })
            } />
    );
}
